## Code Example
```javascript
// Pseudo-test asserting per-tenant SOT parity
const tenants = seedTenants(100);
for (const t of tenants) {
  const hashA = hash(fetch(t, 'Contacts'));
  const hashB = hash(fetch(t, 'Activities'));
  const hashC = hash(fetch(t, 'Deals'));
  assert(hashA === hashB && hashB === hashC, `Pariy fail for ${t.id}`);
}
```

